.github/workflows/release-please.yml.content:
name: release-please
on: {push: {branches: [main]}}
permissions: {contents: read}
jobs:
  propose:
    uses: 7K-Hiroba/workflows/.github/workflows/release-please.yml@b26b53f5ba58a27d1973fec6dfa6469d0b93ba62 # v1.1.0
