charts/matrix-app/templates/_helpers.tpl.content:
{{- define "matrix-app.fullname" -}}
{{ .Release.Name }}
{{- end }}
{{- define "matrix-app.labels" -}}
app.kubernetes.io/name: matrix-app
app.kubernetes.io/instance: {{ .Release.Name }}
app.kubernetes.io/version: {{ .Chart.AppVersion | quote }}
{{- end }}

charts/matrix-app/templates/deployment.y.content:
apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "matrix-app.fullname" . }}
  labels: {{ include "matrix-app.labels" . | nindent 4 }}
spec:
  replicas: {{ .Values.replicaCount }}
  selector:
    matchLabels:
      app.kubernetes.io/name: matrix-app
      app.kubernetes.io/instance: {{ .Release.Name }}
  template:
    metadata:
      labels: {{ include "matrix-app.labels" . | nindent 8 }}
    spec:
      automountServiceAccountToken: false
      securityContext:
        runAsNonRoot: true
        runAsUser: 101
        runAsGroup: 101
        fsGroup: 101
        seccompProfile: {type: RuntimeDefault}
      containers:
        - name: app
{{ if .Values.image.digest }}
          image: "{{ .Values.image.repository }}@{{ .Values.image.digest }}"
{{ else }}
          image: "{{ .Values.image.repository }}:{{ .Values.image.tag }}"
{{ end }}
          imagePullPolicy: {{ .Values.image.pullPolicy }}
          ports:
            - {name: http, containerPort: 8080}
          securityContext:
            allowPrivilegeEscalation: false
            readOnlyRootFilesystem: true
            capabilities: {drop: [ALL]}
          readinessProbe:
            httpGet: {path: /, port: http}
            periodSeconds: 2
            failureThreshold: 15
          livenessProbe:
            httpGet: {path: /, port: http}
            periodSeconds: 10
          resources: {{ .Values.resources | toYaml | nindent 12 }}
          volumeMounts:
            - {name: nginx-cache, mountPath: /var/cache/nginx}
            - {name: nginx-run, mountPath: /var/run}
            - {name: nginx-tmp, mountPath: /tmp}
      volumes:
        - {name: nginx-cache, emptyDir: {}}
        - {name: nginx-run, emptyDir: {}}
        - {name: nginx-tmp, emptyDir: {}}

charts/matrix-app/templates/service.yaml.content:
apiVersion: v1
kind: Service
metadata:
  name: {{ include "matrix-app.fullname" . }}
  labels: {{ include "matrix-app.labels" . | nindent 4 }}
spec:
  type: {{ .Values.service.type }}
  selector:
    app.kubernetes.io/name: matrix-app
    app.kubernetes.io/instance: {{ .Release.Name }}
  ports:
    - name: http
      port: {{ .Values.service.port }}
      targetPort: http

release-please-config.json.content:
{
  "$schema": "https://raw.githubusercontent.com/googleapis/release-please/main/schemas/config.json",
  "separate-pull-requests": false,
  "include-component-in-tag": true,
  "include-v-in-tag": true,
  "tag-separator": "-v",
  "pull-request-title-pattern": "chore: release ${component} ${version}",
  "packages": {
    "charts/matrix-app": {
      "release-type": "simple",
      "changelog-path": "CHANGELOG.md",
      "bump-minor-pre-major": true,
      "bump-patch-for-minor-pre-major": true,
      "extra-files": [
        "Chart.yaml"
      ],
      "component": "chart-matrix-app"
    },
    "packages/matrix-app": {
      "release-type": "simple",
      "changelog-path": "CHANGELOG.md",
      "bump-minor-pre-major": true,
      "bump-patch-for-minor-pre-major": true,
      "extra-files": [
        "package.yaml"
      ],
      "component": "package-matrix-app"
    }
  }
}

renovate.json.content:
{
  "$schema": "https://docs.renovatebot.com/renovate-schema.json",
  "extends": ["config:recommended"],
  "pinDigests": true,
  "packageRules": [
    {
      "description": "Review trusted workflow SHAs and action updates manually",
      "matchManagers": ["github-actions"],
      "automerge": false
    },
    {
      "description": "Group reviewed non-major SDK and chart dependency updates",
      "matchUpdateTypes": ["minor", "patch", "digest", "pinDigest"],
      "groupName": "non-major dependencies",
      "automerge": false
    }
  ]
}
